/* L8 ★ olympiad */
G(8,()=>{const r=ch('делится на 8',['делится на 12,5','равно 125','может быть любым']);
return {type:'choice',q:'В опросе доля одного ответа ровно 12,5 % (то есть '+F(1,8)+'). Что можно сказать о числе опрошенных?',...r,
short:F(1,8)+' от N — целое, значит N делится на 8.',
explain:`12,5 % = ${F(1,8)}. Число ответивших так — ${F('N',8)} — должно быть <b>целым</b> (людей не бывает «полтора»). Значит, N <b>делится на 8</b>.`,
explain2:`Попробуй N = 10: 12,5 % от 10 = 1,25 человека — так не бывает. N = 8: 1 человек ✅; N = 16: 2 ✅.`};},false,true);
G(8,()=>{let d,parts,pc,minN;for(;;){d=pick([8,16,20,40,25,24]);const a=R(1,d-2),b=R(1,d-a-1),c=d-a-b;parts=[a,b,c];pc=parts.map(x=>x*100/d);if(pc.some(p=>Math.abs(p*1000-Math.round(p*1000))>1e-6))continue;
 minN=0;for(let n=1;n<=1000;n++){if(pc.every(p=>Math.abs(p*n/100-Math.round(p*n/100))<1e-9)){minN=n;break;}}if(minN>=4)break;}
const g=gcd(gcd(parts[0],parts[1]),parts[2]);ok(minN===d/g,'minN');const pf=pc.map(p=>N(rnd(p))+' %');
return {type:'num',q:`В опросе было три варианта ответа. Их доли: ${pf.join(', ')}. Какое <b>наименьшее</b> число людей могли опросить?`,ans:minN,
hint:'Переведи проценты в несократимые дроби.',
short:`${pc.map((p,i)=>`${pf[i]} = ${F(parts[i]/g,d/g)}`).join(', ')} → N делится на ${minN}.`,
explain:`Переводим в дроби: ${pc.map((p,i)=>{const gg=gcd(parts[i],d);return `${pf[i]} = ${F(parts[i]/gg,d/gg)}`;}).join(', ')}.<br>Каждая группа — целое число людей, поэтому N должно делиться на каждый знаменатель. Наименьшее такое N — <b>${minN}</b>.<br>Проверка: ${pc.map(p=>N(p*minN/100)).join(' + ')} = ${minN} ✅.`,
explain2:`Перебор: ${range(1,Math.min(minN,6)).map(n=>`N = ${n}: ${pc.map(p=>N(rnd(p*n/100))).join(', ')}${n===minN?' ✅':' ❌'}`).join('; ')}${minN>6?` … первое подходящее — N = ${minN}`:''}.`};},true);
G(8,()=>{const c=cutData();ok(Math.abs((c.B-c.y0)/(c.A-c.y0)-c.t)<1e-9,'cut');
return {type:'num',q:`На диаграмме два столбика: A = ${c.A} и B = ${c.B}. Столбик B нарисован ровно в ${c.t} раза выше столбика A, потому что ось обрезана. С какого числа начинается ось?`,ans:c.y0,
hint:'Пусть ось начинается с y. Тогда высоты на рисунке — это A − y и B − y.',
short:`${c.B} − y = ${c.t}(${c.A} − y) → y = ${c.y0}.`,
explain:`Пусть ось начинается с y. Высоты на рисунке: ${c.A} − y и ${c.B} − y.<br>Условие: ${c.B} − y = ${c.t} · (${c.A} − y).<br>${c.B} − y = ${c.t*c.A} − ${c.t}y → ${c.t}y − y = ${c.t*c.A} − ${c.B} → ${c.t-1}y = ${c.t*c.A-c.B} → y = <b>${c.y0}</b>.`,
explain2:`Проверка: ${c.A} − ${c.y0} = ${c.A-c.y0}, ${c.B} − ${c.y0} = ${c.B-c.y0}, и ${c.B-c.y0} : ${c.A-c.y0} = ${c.t} ✅.<br>Другой путь: разница B − A = ${c.B-c.A} — это (${c.t} − 1) «высот A». Значит, высота A = ${c.B-c.A} : ${c.t-1} = ${c.h}, а ось начинается с ${c.A} − ${c.h} = ${c.y0}.`};},true);
G(8,()=>{let u,k;do{u=pick([2,3,4,5,6,8,9,10,12,15]);k=R(2,15);}while(k*u>=180);const tot=360/u;
return {type:'num',q:`На круговой диаграмме сектор «Roblox» больше сектора «Minecraft» на ${k*u}°. Это значит, что Roblox выбрали на ${k} человек больше. Сколько всего человек опросили?`,ans:tot,
hint:'Сколько градусов приходится на одного человека?',
short:`${k*u} : ${k} = ${u}° на человека; 360 : ${u} = ${tot}.`,
explain:`1) Разнице ${k} человек соответствуют ${k*u}° → на одного человека ${k*u} : ${k} = ${u}°.<br>2) Весь круг 360° → всего 360 : ${u} = <b>${tot}</b> человек.`,
explain2:`Пропорция: ${F(k,'N')} = ${F(k*u,360)} → N = ${k} · 360 : ${k*u} = ${tot}.`};},true);
G(8,()=>{// rounding paradox
const cand=[[33,33,33],[33,33,34],[17,17,66],[14,43,43],[11,22,67],[40,40,20],[29,29,43],[67,17,17],[13,38,50],[45,45,9]];
let tg,minN,ex;for(;;){tg=pick(cand);minN=0;ex=null;for(let n=1;n<=200&&!minN;n++){for(let a=0;a<=n&&!minN;a++)for(let b=0;a+b<=n;b++){const c=n-a-b;if(Math.round(100*a/n)===tg[0]&&Math.round(100*b/n)===tg[1]&&Math.round(100*c/n)===tg[2]){minN=n;ex=[a,b,c];break;}}}if(minN>=3)break;}
return {type:'num',q:`В опросе три ответа. После округления до целых процентов их доли: ${tg.join(' %, ')} %. Какое <b>наименьшее</b> число людей могло участвовать в опросе? (Округляем по обычным правилам: 0,5 и больше — вверх.)`,ans:minN,
hint:'Перебирай число участников N = 1, 2, 3, … и проверяй, можно ли получить такие округления.',
short:`N = ${minN}: ${ex.map(a=>`${a}/${minN} ≈ ${N(rnd(Math.round(1000*a/minN)/10))} %`).join(', ')}.`,
explain:`Перебираем N по порядку. Для каждого N пробуем разбить людей на три группы a + b + c = N и округлить 100a/N, 100b/N, 100c/N.<br>Первое подходящее: <b>N = ${minN}</b>, группы ${ex.join(', ')}:<br>${ex.map((a,i)=>`${a} : ${minN} = ${N(rnd(Math.round(10000*a/minN)/100))} % → ${tg[i]} %`).join('<br>')}.<br>Для меньших N такого разбиения нет.${sum(tg)!==100?`<br>Заметь: сумма округлённых долей ${sum(tg)} %, а не 100 % — так бывает из-за округления!`:''}`,
explain2:`Почему не меньше? ${minN>3?`Например, при N = ${minN-1} доли могут быть только кратны ${N(rnd(100/(minN-1)))} % — нужных округлений не получить.`:''} Вывод: проценты в опросах всегда округлены, и по ним можно оценить, сколько людей опросили. Это любимый приём олимпиад.`};},true);

/* ---------- widgets ---------- */
function onTheory(root){
  const w=root.querySelector('#w-pie');
  if(w){const L=['Minecraft','Roblox','Brawl Stars'];
    w.innerHTML=`<b>Собери круговую диаграмму: сколько человек выбрали каждую игру?</b>${L.map((l,i)=>`<label>${l}: <input type="range" id="pp${i}" min="0" max="20" value="${[10,6,4][i]}"><output id="po${i}"></output></label>`).join('')}<div id="ppic" class="fig"></div><div id="pout" style="line-height:1.7"></div>`;
    const u=()=>{const v=L.map((_,i)=>+w.querySelector('#pp'+i).value);L.forEach((_,i)=>w.querySelector('#po'+i).textContent=v[i]);const t=sum(v);
      if(!t){w.querySelector('#ppic').innerHTML='';w.querySelector('#pout').innerHTML='Никого не опросили — круга нет.';return;}
      w.querySelector('#ppic').innerHTML=pie(L,v);
      w.querySelector('#pout').innerHTML=`Всего: <b>${t}</b> чел. На одного человека: 360° : ${t} = ${N(Math.round(360/t*100)/100)}°.<br>`+L.map((l,i)=>`${i+1}. ${l}: ${v[i]} из ${t} = <b>${N(Math.round(v[i]/t*1000)/10)} %</b> = <b>${N(Math.round(v[i]/t*3600)/10)}°</b>`).join('<br>');};
    w.querySelectorAll('input').forEach(i=>i.oninput=u);u();}
  const a=root.querySelector('#w-axis');
  if(a){a.innerHTML=`<b>Обрежь ось и посмотри, как «растёт» разница</b><label>Ось начинается с: <input type="range" id="ax" min="0" max="51" value="0"><output id="axo"></output></label><div id="axpic" class="fig"></div><div id="axout"></div>`;
    const A=52,B=56;const u=()=>{const y0=+a.querySelector('#ax').value;a.querySelector('#axo').textContent=y0;const step=y0>=40?2:y0>=20?5:10;const lo=Math.floor(y0/step)*step;
      a.querySelector('#axpic').innerHTML=bars(['A','B'],[A,B],{step,y0:lo,top:Math.max(lo+step,Math.ceil(B/step)*step),h:140});
      a.querySelector('#axout').innerHTML=`Настоящие значения: A = ${A}, B = ${B}, B : A ≈ <b>${N(Math.round(B/A*100)/100)}</b>.<br>На рисунке B выше A в <b>${N(Math.round((B-lo)/(A-lo)*100)/100)}</b> раза.${lo>0?' Ось обрезана — картинка врёт!':' Ось с нуля — честно.'}`;};
    a.querySelector('#ax').oninput=u;u();}
}

